if (!function_exists('wfx_has')) {
    function wfx_has(array $roles, array $allowed): bool { return (bool)array_intersect($roles, $allowed); }
    function wfx_table_exists(PDO $pdo, string $table): bool {
        static $memo=[]; if (isset($memo[$table])) return $memo[$table];
        if (!preg_match('/^[a-z0-9_]+$/i',$table)) return false;
        try { $pdo->query("SELECT 1 FROM `{$table}` LIMIT 1"); return $memo[$table]=true; } catch(Throwable $e) { return $memo[$table]=false; }
    }
    function wfx_visit_sql(PDO $pdo, string $page, array $roles, array $user, int $limit=100): array {
        $sql="SELECT k.*,p.nama AS nama_pasien,p.no_rm,u.nama_unit,d.nama AS nama_dokter,a.no_antrean,a.status AS status_antrean
              FROM kunjungan k JOIN pasien p ON p.id_pasien=k.id_pasien
              LEFT JOIN unit u ON u.id_unit=k.id_unit
              LEFT JOIN pegawai d ON d.id_pegawai=k.id_dokter
              LEFT JOIN antrean a ON a.id_kunjungan=k.id_kunjungan";
        $where=[]; $params=[];
        if (in_array('DOKTER',$roles,true) && in_array($page,['emr','outpatient','cpoe','inpatient','igd'],true)) {
            if (!empty($user['id_pegawai'])) { $where[]='k.id_dokter=?'; $params[]=(int)$user['id_pegawai']; }
            else { $where[]='1=0'; }
        }
        if ($page==='inpatient') $where[]="k.tipe_pelayanan='Rawat Inap'";
        if ($page==='igd') $where[]="k.tipe_pelayanan='IGD'";
        if (in_array($page,['outpatient','emr','cpoe'],true)) $where[]="k.tipe_pelayanan='Rawat Jalan'";
        if ($where) $sql.=' WHERE '.implode(' AND ',$where);
        $sql.=' ORDER BY k.tanggal DESC,k.id_kunjungan DESC LIMIT '.max(1,min(200,$limit));
        $q=$pdo->prepare($sql);$q->execute($params);return $q->fetchAll(PDO::FETCH_ASSOC);
    }
    function wfx_visit_detail(PDO $pdo, int $id): ?array {
        $q=$pdo->prepare("SELECT k.*,p.nama AS nama_pasien,p.no_rm,p.nik,p.tanggal_lahir,p.jenis_kelamin,p.alamat,p.no_telp,u.nama_unit,d.nama AS nama_dokter,a.no_antrean,a.status AS status_antrean
          FROM kunjungan k JOIN pasien p ON p.id_pasien=k.id_pasien LEFT JOIN unit u ON u.id_unit=k.id_unit LEFT JOIN pegawai d ON d.id_pegawai=k.id_dokter LEFT JOIN antrean a ON a.id_kunjungan=k.id_kunjungan WHERE k.id_kunjungan=? LIMIT 1");
        $q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);return $r?:null;
    }
    function wfx_form_open(string $action, int $visit, string $returnPage): void {
        echo '<form method="post" action="'.e(APP_BASE_URL).'/workflow_action.php" class="wfx-form">';
        echo '<input type="hidden" name="csrf" value="'.e(csrf_token()).'">';
        echo '<input type="hidden" name="action" value="'.e($action).'">';
        echo '<input type="hidden" name="id_kunjungan" value="'.(int)$visit.'">';
        echo '<input type="hidden" name="return_page" value="'.e($returnPage).'">';
    }
    function wfx_input(string $name,string $label,string $value='',string $type='text',string $hint=''): void {
        echo '<label class="wfx-field"><span>'.e($label).'</span><input type="'.e($type).'" name="'.e($name).'" value="'.e($value).'">'.($hint?'<small>'.e($hint).'</small>':'').'</label>';
    }
    function wfx_textarea(string $name,string $label,string $value='',int $rows=3,string $hint=''): void {
        echo '<label class="wfx-field"><span>'.e($label).'</span><textarea name="'.e($name).'" rows="'.$rows.'">'.e($value).'</textarea>'.($hint?'<small>'.e($hint).'</small>':'').'</label>';
    }
    function wfx_select(string $name,string $label,array $options,string $selected=''): void {
        echo '<label class="wfx-field"><span>'.e($label).'</span><select name="'.e($name).'">';
        foreach($options as $value=>$text) echo '<option value="'.e($value).'" '.((string)$selected===(string)$value?'selected':'').'>'.e($text).'</option>';
        echo '</select></label>';
    }
    function wfx_patient_card(array $v): void {
        $age=''; if(!empty($v['tanggal_lahir'])){try{$age=(new DateTime($v['tanggal_lahir']))->diff(new DateTime())->y.' th';}catch(Throwable $e){}}
        echo '<div class="wfx-patient"><div><strong>'.e($v['nama_pasien']??'Pasien').' · RM '.e($v['no_rm']??'—').'</strong><small>No. Kunjungan: '.e($v['no_kunjungan']??('KJ-'.$v['id_kunjungan'])).' · '.e($v['tipe_pelayanan']??'').' · '.e($v['tanggal']??'').'</small><small>'.e($v['jenis_kelamin']??'').' '.e($age).' · '.e($v['alamat']??'').'</small></div><div class="wfx-badges"><span>'.e($v['nama_unit']??'Unit belum ditentukan').'</span><span>'.e($v['nama_dokter']??'Dokter belum ditentukan').'</span><span>Antrean '.e($v['no_antrean']??'—').'</span><span>'.e($v['status']??'Terdaftar').'</span></div></div>';
    }
    function wfx_orders(PDO $pdo,int $visit): array {
        $q=$pdo->prepare("SELECT o.*,r.hasil_teks,r.hasil_angka,r.satuan,r.nilai_rujukan,r.penanda_abnormal,r.teknik_pemeriksaan,r.temuan,r.kesan,r.status_hasil,r.catatan_reviewer,r.catatan_validator FROM simrs_wf_orders o LEFT JOIN simrs_wf_results r ON r.id_order=o.id_order WHERE o.id_kunjungan=? ORDER BY o.dibuat_pada DESC,o.id_order DESC");$q->execute([$visit]);return $q->fetchAll(PDO::FETCH_ASSOC);
    }
    function lab_inline_results(PDO $pdo,int $orderId,?string $note): void {
        $q=$pdo->prepare('SELECT nama_pemeriksaan,nilai_hasil,satuan,nilai_rujukan,penanda FROM simrs_wf_lab_items WHERE id_order=? ORDER BY id_lab_item');$q->execute([$orderId]);$its=$q->fetchAll(PDO::FETCH_ASSOC);
        if(!$its){ echo '<br>'.nl2br(e((string)$note)); return; }
        echo '<ul style="margin:6px 0 0;padding-left:18px">';
        foreach($its as $it){ $flag=['low'=>' (rendah)','high'=>' (tinggi)','critical'=>' (KRITIS)'][$it['penanda']??'']??''; echo '<li>'.e($it['nama_pemeriksaan']).': <b>'.e($it['nilai_hasil']).' '.e($it['satuan']).'</b>'.e($flag).' <small class="muted">rujukan '.e($it['nilai_rujukan']).'</small></li>'; }
        echo '</ul>';
    }
    function wfx_money($v): string { return 'Rp '.number_format((float)$v,0,',','.'); }
    function wfx_status(string $s): string { return '<span class="wfx-status">'.e(str_replace('_',' ',$s)).'</span>'; }
    function wfx_selected_visit(PDO $pdo,array $visits): ?array {
        $id=(int)($_GET['id_kunjungan']??0);if(!$id)return null;
        $v=wfx_visit_detail($pdo,$id);if(!$v)return null;
        // Prevent doctor from opening another doctor's assigned encounter.
        if(in_array('DOKTER',user_roles($pdo,(int)($_SESSION['user_id']??0)),true) && (empty($GLOBALS['user']['id_pegawai']) || empty($v['id_dokter']) || (int)$v['id_dokter']!==(int)$GLOBALS['user']['id_pegawai']))return null;
        if(($_GET['page']??'')==='igd' && ($v['tipe_pelayanan']??'')!=='IGD')return null;
        if(($_GET['page']??'')==='inpatient' && ($v['tipe_pelayanan']??'')!=='Rawat Inap')return null;
        return $v;
    }
    function wfx_visit_picker(array $visits,string $page): void {
        echo '<section class="wfx-panel"><div class="wfx-panel-head"><div><h2>Daftar kunjungan</h2><p>Pilih episode pelayanan untuk membuka detail dan mengisi tugas.</p></div><span class="wfx-count">'.count($visits).' kunjungan</span></div>';
        if(!$visits){echo '<div class="wfx-empty">Belum ada kunjungan yang tersedia. Pastikan Admisi telah membuat kunjungan, bukan hanya data identitas pasien.</div></section>';return;}
        echo '<div class="wfx-table-wrap"><table class="wfx-table"><thead><tr><th>Pasien / No. RM</th><th>No. Kunjungan</th><th>Unit</th><th>Dokter</th><th>Jenis</th><th>Antrean</th><th>Status</th><th></th></tr></thead><tbody>';
        foreach($visits as $v){echo '<tr><td><b>'.e($v['nama_pasien']).'</b><br><small>RM '.e($v['no_rm']).'</small></td><td>'.e($v['no_kunjungan']).'</td><td>'.e($v['nama_unit']??'—').'</td><td>'.e($v['nama_dokter']??'—').'</td><td>'.e($v['tipe_pelayanan']).'</td><td>'.e($v['no_antrean']??'—').'</td><td>'.wfx_status((string)$v['status']).'</td><td><a class="wfx-btn wfx-btn-primary" href="index.php?page='.e($page).'&id_kunjungan='.(int)$v['id_kunjungan'].'">Buka</a></td></tr>';}
        echo '</tbody></table></div></section>';
    }
}

