  <?php $q=$pdo->query("SELECT o.*,k.no_kunjungan,p.nama AS nama_pasien,p.no_rm,r.* FROM simrs_wf_orders o JOIN kunjungan k ON k.id_kunjungan=o.id_kunjungan JOIN pasien p ON p.id_pasien=k.id_pasien LEFT JOIN simrs_wf_results r ON r.id_order=o.id_order WHERE o.jenis_order='RADIOLOGI' ORDER BY o.dibuat_pada DESC LIMIT 150");$items=$q->fetchAll(PDO::FETCH_ASSOC);if(!$items): ?><div class="wfx-empty">Belum ada permintaan radiologi.</div><?php endif; ?>
