    <?php if(wfx_has($roles,['RADIOGRAFER'])&&$o['status_order']==='ordered'): wfx_form_open('accept_order',(int)$o['id_kunjungan'],'radiology'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><button class="wfx-btn" type="submit">Terima order / Mulai pemeriksaan</button></form><?php endif; ?>
    <?php if(wfx_has($roles,['RADIOGRAFER'])&&$o['status_order']==='in_progress'): wfx_form_open('submit_radiology_result',(int)$o['id_kunjungan'],'radiology'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><div class="wfx-grid"><?php wfx_textarea('teknik_pemeriksaan','Teknik / protokol pemeriksaan','',3); ?><?php wfx_textarea('temuan','Temuan teknis / deskripsi awal','',4); ?><?php wfx_textarea('hasil_teks','Catatan tambahan','',2); ?></div><button class="wfx-btn wfx-btn-primary" type="submit">Kirim Temuan ke Dokter Radiologi</button></form><?php endif; ?>
