        <?php wfx_form_open('finalize_radiology_result',(int)$o['id_kunjungan'],'radiology'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><?php wfx_textarea('kesan','Kesan / interpretasi radiologi *','',4); ?><?php wfx_textarea('catatan_reviewer','Catatan dokter radiologi','',2); ?><button class="wfx-btn wfx-btn-success" type="submit">Finalisasi & Tanda Tangani Laporan</button></form>
        <?php wfx_form_open('request_radiology_revision',(int)$o['id_kunjungan'],'radiology'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><?php wfx_textarea('catatan_reviewer','Alasan koreksi untuk Radiografer *','',2); ?><button class="wfx-btn wfx-btn-danger" type="submit">Kembalikan ke Radiografer</button></form>
      </div>
    <?php endif; ?>
  </section><?php endforeach; ?>

<?php elseif($page==='pharmacy'): ?>
  <p class="wfx-intro">Antrean resep dari dokter. Apoteker memeriksa kelengkapan instruksi, melakukan verifikasi, dan mencatat penyerahan penuh atau sebagian. Pemberian obat di bangsal dicatat Perawat melalui e-MAR.</p>
  <?php $q=$pdo->query("SELECT o.*,k.no_kunjungan,p.nama AS nama_pasien,p.no_rm,e.riwayat_alergi FROM simrs_wf_orders o JOIN kunjungan k ON k.id_kunjungan=o.id_kunjungan JOIN pasien p ON p.id_pasien=k.id_pasien LEFT JOIN simrs_wf_emr e ON e.id_kunjungan=k.id_kunjungan WHERE o.jenis_order='FARMASI' ORDER BY o.dibuat_pada DESC LIMIT 150");$items=$q->fetchAll(PDO::FETCH_ASSOC);if(!$items): ?><div class="wfx-empty">Belum ada resep dokter.</div><?php endif; ?>
  <?php foreach($items as $o): ?><section class="wfx-panel"><div class="wfx-panel-head"><div><h2><?= e($o['nama_pasien']) ?> · RM <?= e($o['no_rm']) ?></h2><p><?= e($o['no_kunjungan']) ?> · <?= e($o['no_order']) ?></p></div><?= wfx_status($o['status_order']) ?></div><div class="wfx-subpanel"><b><?= e($o['nama_layanan']) ?></b><?php if(!empty($o['riwayat_alergi'])): ?><p class="wfx-mark">Periksa riwayat alergi: <?= e($o['riwayat_alergi']) ?></p><?php endif; ?><p>Dosis: <?= e($o['dosis']) ?> · Rute: <?= e($o['rute']) ?> · Frekuensi: <?= e($o['frekuensi']) ?> · Durasi: <?= e($o['durasi']) ?></p><p>Jumlah: <?= e($o['jumlah']) ?> <?= e($o['satuan_jumlah']) ?> · Diserahkan: <?= e($o['jumlah_diserahkan']) ?></p><p><?= nl2br(e($o['instruksi'])) ?></p></div>
    <?php if(wfx_has($roles,['APOTEKER'])&&$o['status_order']==='ordered'): wfx_form_open('accept_order',(int)$o['id_kunjungan'],'pharmacy'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><button class="wfx-btn" type="submit">Terima resep</button></form><?php endif; ?>
    <?php if(wfx_has($roles,['APOTEKER'])&&$o['status_order']==='in_progress'): wfx_form_open('verify_prescription',(int)$o['id_kunjungan'],'pharmacy'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><?php wfx_textarea('catatan_farmasi','Hasil verifikasi farmasi / klarifikasi','',2); ?><button class="wfx-btn wfx-btn-primary" type="submit">Verifikasi Resep</button></form><?php endif; ?>
    <?php if(wfx_has($roles,['APOTEKER'])&&in_array($o['status_order'],['verified','partially_dispensed'],true)): wfx_form_open('dispense_prescription',(int)$o['id_kunjungan'],'pharmacy'); ?><input type="hidden" name="id_order" value="<?= (int)$o['id_order'] ?>"><?php wfx_input('jumlah_diserahkan','Jumlah diserahkan kali ini',((float)$o['jumlah']-(float)$o['jumlah_diserahkan']),'number'); ?><?php wfx_textarea('catatan_farmasi','Catatan penyerahan','',2); ?><button class="wfx-btn wfx-btn-success" type="submit">Catat Penyerahan</button></form><?php endif; ?>
    <?php $q2=$pdo->prepare('SELECT * FROM simrs_wf_dispenses WHERE id_order=? ORDER BY diserahkan_pada DESC');$q2->execute([$o['id_order']]);$disp=$q2->fetchAll(PDO::FETCH_ASSOC);if($disp): ?><div class="wfx-section"><b>Riwayat penyerahan</b><ul><?php foreach($disp as $d): ?><li><?= e(format_datetime($d['diserahkan_pada'])) ?> · <?= e($d['jumlah_diserahkan']) ?> · <?= e($d['catatan']) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
  </section><?php endforeach; ?>

<?php elseif($page==='billing'): ?>
  <p class="wfx-intro">Billing hanya menerima kunjungan yang EMR-nya sudah ditandatangani dan seluruh order telah selesai. Kasir menetapkan tarif berdasarkan daftar tarif rumah sakit; Asuransi mencatat proses verifikasi klaim. Modul ini belum terhubung ke gateway, BPJS, atau INA-CBG.</p>
  <?php $bills=$pdo->query("SELECT b.*,k.no_kunjungan,p.nama AS nama_pasien,p.no_rm,k.tipe_pelayanan FROM simrs_wf_bills b JOIN kunjungan k ON k.id_kunjungan=b.id_kunjungan JOIN pasien p ON p.id_pasien=k.id_pasien ORDER BY b.dibuat_pada DESC LIMIT 150")->fetchAll(PDO::FETCH_ASSOC);if(!$bills): ?><div class="wfx-empty">Belum ada tagihan. Dokter harus menyelesaikan dan mengirim episode dari halaman EMR.</div><?php endif; ?>
  <?php foreach($bills as $b): $bill=(int)$b['id_bill'];$q=$pdo->prepare('SELECT * FROM simrs_wf_bill_items WHERE id_bill=? ORDER BY id_bill_item');$q->execute([$bill]);$lines=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT COALESCE(SUM(jumlah_bayar),0) FROM simrs_wf_payments WHERE id_bill=?');$q->execute([$bill]);$paid=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT * FROM simrs_wf_claims WHERE id_bill=?');$q->execute([$bill]);$claim=$q->fetch(PDO::FETCH_ASSOC); ?>
  <section class="wfx-panel"><div class="wfx-panel-head"><div><h2><?= e($b['nama_pasien']) ?> · RM <?= e($b['no_rm']) ?></h2><p><?= e($b['no_kunjungan']) ?> · <?= e($b['no_tagihan']) ?> · <?= e($b['tipe_pelayanan']) ?></p></div><?= wfx_status($b['status_tagihan']) ?></div>
    <div class="wfx-table-wrap"><table class="wfx-table"><thead><tr><th>Kategori</th><th>Uraian</th><th>Qty</th><th>Tarif satuan</th><th>Total</th></tr></thead><tbody><?php foreach($lines as $line): ?><tr><td><?= e($line['kategori']) ?></td><td><?= e($line['uraian']) ?></td><td><?= e($line['jumlah']) ?></td><td><?= wfx_money($line['tarif_satuan']) ?></td><td><?= wfx_money($line['total_item']) ?></td></tr><?php endforeach; ?></tbody></table></div>
    <div class="wfx-metric-grid"><div class="wfx-metric"><small>Total tagihan</small><strong><?= wfx_money($b['total']) ?></strong></div><div class="wfx-metric"><small>Sudah dibayar</small><strong><?= wfx_money($paid) ?></strong></div><div class="wfx-metric"><small>Sisa tagihan</small><strong><?= wfx_money(max(0,(float)$b['total']-$paid)) ?></strong></div><div class="wfx-metric"><small>Status</small><strong style="font-size:16px"><?= e($b['status_tagihan']) ?></strong></div></div>
    <?php if(wfx_has($roles,['KASIR'])&&$b['status_tagihan']==='needs_tariff'): ?><div class="wfx-subpanel"><h3>Penetapan tarif resmi</h3><p class="wfx-help">Isi nilai tarif berdasarkan tarif RS yang berlaku. Jangan menggunakan harga contoh tanpa verifikasi.</p><?php wfx_form_open('set_bill_tariffs',(int)$b['id_kunjungan'],'billing'); ?><input type="hidden" name="id_bill" value="<?= $bill ?>"><?php foreach($lines as $line): ?><label class="wfx-field"><span><?= e($line['uraian']) ?> · Qty <?= e($line['jumlah']) ?></span><input type="number" step="1" min="0" name="tarif[<?= (int)$line['id_bill_item'] ?>]" value="0" required></label><?php endforeach; ?><button class="wfx-btn wfx-btn-primary" type="submit">Konfirmasi Tarif & Siapkan Pembayaran</button></form></div><?php endif; ?>
    <?php if(wfx_has($roles,['KASIR'])&&in_array($b['status_tagihan'],['await_payment','partially_paid'],true)): ?><div class="wfx-subpanel"><h3>Penerimaan pembayaran</h3><?php wfx_form_open('record_payment',(int)$b['id_kunjungan'],'billing'); ?><input type="hidden" name="id_bill" value="<?= $bill ?>"><div class="wfx-grid-3"><?php wfx_input('jumlah_bayar','Jumlah dibayar (Rp)',max(0,(float)$b['total']-$paid),'number'); ?><?php wfx_select('metode_pembayaran','Metode',['Tunai'=>'Tunai','Transfer'=>'Transfer','Debit'=>'Debit','Kartu Kredit'=>'Kartu Kredit','Penjamin'=>'Penjamin','QRIS'=>'QRIS']); ?><?php wfx_input('referensi','Nomor referensi / bukti'); ?></div><button class="wfx-btn wfx-btn-success" type="submit">Catat Pembayaran</button></form></div><?php endif; ?>
    <?php if(wfx_has($roles,['ASURANSI'])): ?><div class="wfx-subpanel"><h3>Verifikasi penjamin / klaim</h3><?php if(!$claim): wfx_form_open('submit_claim',(int)$b['id_kunjungan'],'billing'); ?><input type="hidden" name="id_bill" value="<?= $bill ?>"><div class="wfx-grid"><?php wfx_input('nama_penjamin','Nama penjamin'); ?><?php wfx_input('no_peserta','Nomor peserta / polis'); ?><?php wfx_input('no_klaim','Nomor pengajuan klaim'); ?><?php wfx_input('jumlah_diajukan','Jumlah diajukan (Rp)',$b['total'],'number'); ?></div><button class="wfx-btn" type="submit">Ajukan Klaim</button></form><?php else: ?><p><b><?= e($claim['nama_penjamin']) ?></b> · Peserta <?= e($claim['no_peserta']) ?> · Klaim <?= e($claim['no_klaim']) ?></p><p>Status: <?= wfx_status($claim['status_klaim']) ?> · Diajukan <?= wfx_money($claim['jumlah_diajukan']) ?> · Disetujui <?= wfx_money($claim['jumlah_disetujui']) ?></p><p><?= nl2br(e($claim['catatan_verifikasi'])) ?></p><?php if($claim['status_klaim']==='submitted'): wfx_form_open('review_claim',(int)$b['id_kunjungan'],'billing'); ?><input type="hidden" name="id_claim" value="<?= (int)$claim['id_claim'] ?>"><?php wfx_select('status_klaim','Keputusan',['need_revision'=>'Perlu revisi','approved'=>'Disetujui','partially_approved'=>'Disetujui sebagian','rejected'=>'Ditolak']); ?><?php wfx_input('jumlah_disetujui','Jumlah disetujui (Rp)',$claim['jumlah_diajukan'],'number'); ?><?php wfx_textarea('catatan_verifikasi','Catatan verifikasi','',3); ?><button class="wfx-btn wfx-btn-primary" type="submit">Simpan Keputusan Klaim</button></form><?php endif; ?><?php endif; ?></div><?php endif; ?>
    <?php $q=$pdo->prepare('SELECT * FROM simrs_wf_payments WHERE id_bill=? ORDER BY dibayar_pada DESC');$q->execute([$bill]);$payments=$q->fetchAll(PDO::FETCH_ASSOC);if($payments): ?><div class="wfx-section"><h3>Riwayat pembayaran</h3><ul><?php foreach($payments as $pay): ?><li><?= e(format_datetime($pay['dibayar_pada'])) ?> · <?= wfx_money($pay['jumlah_bayar']) ?> · <?= e($pay['metode_pembayaran']) ?> · <?= e($pay['referensi']) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
  </section><?php endforeach; ?>

<?php elseif($page==='inventory'): ?>
  <p class="wfx-intro">Alur persediaan contoh: Petugas Gudang mengajukan penerimaan/pengeluaran; Kepala Gudang memeriksa dan menyetujui/menolak. Saldo dihitung dari mutasi yang disetujui. Katalog ledger ini merupakan ekstensi workflow dan belum otomatis mengurangi stok tabel farmasi/obat inti.</p>
  <?php $items=$pdo->query("SELECT i.*,COALESCE(m.stok,0) AS stok FROM simrs_wf_stock_items i LEFT JOIN (SELECT id_item,SUM(CASE WHEN jenis_mutasi='IN' THEN jumlah WHEN jenis_mutasi='OUT' THEN -jumlah ELSE 0 END) AS stok FROM simrs_wf_stock_moves WHERE status_mutasi='approved' GROUP BY id_item) m ON m.id_item=i.id_item WHERE i.aktif=1 ORDER BY i.nama_item")->fetchAll(PDO::FETCH_ASSOC); ?>
  <?php if(wfx_has($roles,['KEPALA_GUDANG'])): ?><div class="wfx-panel"><h2>Tambah master barang persediaan</h2><?php wfx_form_open('create_stock_item',0,'inventory'); ?><div class="wfx-grid-3"><?php wfx_input('kode_item','Kode barang'); ?><?php wfx_input('nama_item','Nama barang'); ?><?php wfx_select('kategori','Kategori',['Obat'=>'Obat','BMHP'=>'Bahan Medis Habis Pakai','Alat Kesehatan'=>'Alat Kesehatan','ATK'=>'ATK','Kebersihan'=>'Kebersihan','Operasional'=>'Operasional']); ?><?php wfx_input('satuan','Satuan'); ?><?php wfx_input('stok_minimum','Stok minimum','0','number'); ?></div><button class="wfx-btn wfx-btn-primary" type="submit">Simpan Master Barang</button></form></div><?php endif; ?>
  <div class="wfx-panel"><h2>Kartu stok ringkas</h2><?php if($items): ?><div class="wfx-table-wrap"><table class="wfx-table"><thead><tr><th>Kode</th><th>Nama barang</th><th>Kategori</th><th>Satuan</th><th>Saldo</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['kode_item']) ?></td><td><?= e($i['nama_item']) ?></td><td><?= e($i['kategori']) ?></td><td><?= e($i['satuan']) ?></td><td><b><?= e($i['stok']) ?></b></td><td><?= e($i['stok_minimum']) ?></td><td><?= (float)$i['stok']<=(float)$i['stok_minimum']?'<span class="wfx-mark">Perlu pengadaan</span>':'Memadai' ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="wfx-empty">Belum ada barang pada ledger workflow. Kepala Gudang dapat menambahkan master barang.</div><?php endif; ?></div>
  <?php if(wfx_has($roles,['PETUGAS_GUDANG'])): ?><div class="wfx-panel"><h2>Ajukan mutasi barang</h2><?php wfx_form_open('request_stock_move',0,'inventory'); ?><div class="wfx-grid-3"><?php $opts=[''=>'Pilih barang'];foreach($items as $i)$opts[$i['id_item']]=$i['nama_item'].' (saldo '.$i['stok'].' '.$i['satuan'].')';wfx_select('id_item','Barang',$opts); ?><?php wfx_select('jenis_mutasi','Jenis mutasi',['IN'=>'Penerimaan / masuk','OUT'=>'Pengeluaran / keluar']); ?><?php wfx_input('jumlah','Jumlah','1','number'); ?><?php wfx_input('no_dokumen','Nomor dokumen / referensi'); ?></div><?php wfx_textarea('catatan','Catatan / alasan mutasi','',2); ?><button class="wfx-btn wfx-btn-primary" type="submit">Kirim Permintaan ke Kepala Gudang</button></form></div><?php endif; ?>
  <?php $moves=$pdo->query("SELECT m.*,i.kode_item,i.nama_item,i.satuan FROM simrs_wf_stock_moves m JOIN simrs_wf_stock_items i ON i.id_item=m.id_item ORDER BY m.dibuat_pada DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); ?><div class="wfx-panel"><h2>Persetujuan dan riwayat mutasi</h2><?php if($moves): foreach($moves as $m): ?><div class="wfx-subpanel"><div class="wfx-title-row"><b><?= e($m['nama_item']) ?> · <?= e($m['jenis_mutasi']) ?> <?= e($m['jumlah']) ?> <?= e($m['satuan']) ?></b><?= wfx_status($m['status_mutasi']) ?></div><p><?= e($m['no_dokumen']) ?> · <?= nl2br(e($m['catatan'])) ?> · <?= e(format_datetime($m['dibuat_pada'])) ?></p><?php if(wfx_has($roles,['KEPALA_GUDANG'])&&$m['status_mutasi']==='menunggu_persetujuan'): wfx_form_open('decide_stock_move',0,'inventory'); ?><input type="hidden" name="id_move" value="<?= (int)$m['id_move'] ?>"><div class="wfx-actions"><button class="wfx-btn wfx-btn-success" name="decision" value="approve" type="submit">Setujui</button><button class="wfx-btn wfx-btn-danger" name="decision" value="reject" type="submit">Tolak</button></div></form><?php endif; ?></div><?php endforeach; else: ?><div class="wfx-empty">Belum ada mutasi barang.</div><?php endif; ?></div>

<?php elseif($page==='reporting'): ?>
  <?php $vis=(int)$pdo->query('SELECT COUNT(*) FROM kunjungan')->fetchColumn();$today=(int)$pdo->query('SELECT COUNT(*) FROM kunjungan WHERE DATE(tanggal)=CURDATE()')->fetchColumn();$orders=(int)$pdo->query('SELECT COUNT(*) FROM simrs_wf_orders')->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM simrs_wf_orders WHERE status_order NOT IN ('completed','cancelled')")->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(jumlah_bayar),0) FROM simrs_wf_payments")->fetchColumn();$bills=(int)$pdo->query('SELECT COUNT(*) FROM simrs_wf_bills')->fetchColumn();$ordersBy=$pdo->query("SELECT jenis_order,status_order,COUNT(*) AS jumlah FROM simrs_wf_orders GROUP BY jenis_order,status_order ORDER BY jenis_order,status_order")->fetchAll(PDO::FETCH_ASSOC); ?>
  <p class="wfx-intro">Dashboard pimpinan dan Kepala Gudang: indikator agregat pelayanan, beban order, pembayaran dan status proses. Halaman ini bersifat read-only untuk pemantauan.</p>
  <div class="wfx-metric-grid"><div class="wfx-metric"><small>Total kunjungan</small><strong><?= number_format($vis,0,',','.') ?></strong></div><div class="wfx-metric"><small>Kunjungan hari ini</small><strong><?= number_format($today,0,',','.') ?></strong></div><div class="wfx-metric"><small>Total order layanan</small><strong><?= number_format($orders,0,',','.') ?></strong></div><div class="wfx-metric"><small>Order belum selesai</small><strong><?= number_format($pending,0,',','.') ?></strong></div><div class="wfx-metric"><small>Jumlah tagihan</small><strong><?= number_format($bills,0,',','.') ?></strong></div><div class="wfx-metric"><small>Penerimaan pembayaran tercatat</small><strong style="font-size:18px"><?= wfx_money($revenue) ?></strong></div></div>
  <div class="wfx-panel"><h2>Monitoring order per unit</h2><?php if($ordersBy): ?><div class="wfx-table-wrap"><table class="wfx-table"><thead><tr><th>Jenis order</th><th>Status</th><th>Jumlah</th></tr></thead><tbody><?php foreach($ordersBy as $x): ?><tr><td><?= e($x['jenis_order']) ?></td><td><?= wfx_status($x['status_order']) ?></td><td><?= e($x['jumlah']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="wfx-empty">Belum ada data order untuk dilaporkan.</div><?php endif; ?></div>
  <div class="wfx-panel"><h2>Status tagihan</h2><?php $states=$pdo->query('SELECT status_tagihan,COUNT(*) AS jumlah,SUM(total) AS nominal FROM simrs_wf_bills GROUP BY status_tagihan')->fetchAll(PDO::FETCH_ASSOC);if($states): ?><div class="wfx-table-wrap"><table class="wfx-table"><thead><tr><th>Status</th><th>Jumlah</th><th>Nominal</th></tr></thead><tbody><?php foreach($states as $s): ?><tr><td><?= wfx_status($s['status_tagihan']) ?></td><td><?= e($s['jumlah']) ?></td><td><?= wfx_money($s['nominal']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="wfx-empty">Belum ada tagihan.</div><?php endif; ?></div>
<?php else: ?>
  <div class="wfx-alert">Halaman workflow tidak dikenal. Gunakan menu sesuai role.</div>
<?php endif; ?>
<?php endif; // $missing check ?>
</div>
